const T kEPS = std::numeric_limits<T>::epsilon();
T bestCost = std::numeric_limits<T>::max();
int bestAxis = -1;
T bestPos = T(0);

for (int axis = 0; axis < 3; ++axis) {
    if (bmax[axis] - bmin[axis] < kEPS) continue;

    const int numBins = bins->num_bins[axis];
    if (numBins <= 1) continue;

    std::vector<T> leftSA(numBins - 1, T(0));
    std::vector<T> rightSA(numBins - 1, T(0));
    std::vector<int> leftCount(numBins - 1, 0);
    std::vector<int> rightCount(numBins - 1, 0);

    T binWidth = (bmax[axis] - bmin[axis]) / numBins;

    // Sweep left to right
    real3<T> currentMin = bmin;
    real3<T> currentMax = bmax;
    int runningCount = 0;
    for (int i = 0; i < numBins - 1; ++i) {
        runningCount += bins->bin_count[axis][i];
        leftCount[i] = runningCount;

        T splitPos = bmin[axis] + (i + 1) * binWidth;
        currentMax[axis] = splitPos;
        real3<T> extent = currentMax - currentMin;
        leftSA[i] = T(2) * (extent[0]*extent[1] + extent[1]*extent[2] + extent[2]*extent[0]);
    }

    // Sweep right to left
    currentMin = bmin;
    currentMax = bmax;
    runningCount = 0;
    for (int i = numBins - 1; i > 0; --i) {
        runningCount += bins->bin_count[axis][i];
        rightCount[i-1] = runningCount;

        T splitPos = bmin[axis] + i * binWidth;
        currentMin[axis] = splitPos;
        real3<T> extent = currentMax - currentMin;
        rightSA[i-1] = T(2) * (extent[0]*extent[1] + extent[1]*extent[2] + extent[2]*extent[0]);
    }

    // Find best split
    real3<T> totalExtent = bmax - bmin;
    T parentSA = T(2) * (totalExtent[0]*totalExtent[1] + totalExtent[1]*totalExtent[2] + totalExtent[2]*totalExtent[0]);

    for (int i = 0; i < numBins - 1; ++i) {
        if (leftCount[i] == 0 || rightCount[i] == 0) continue;

        T cost = (leftSA[i] * leftCount[i] + rightSA[i] * rightCount[i]) / parentSA;
        if (cost < bestCost) {
            bestCost = cost;
            bestAxis = axis;
            bestPos = bmin[axis] + (i + 1) * binWidth;
        }
    }
}

if (bestAxis == -1) return false;

cut_pos[0] = bestAxis == 0 ? bestPos : T(0);
cut_pos[1] = bestAxis == 1 ? bestPos : T(0);
cut_pos[2] = bestAxis == 2 ? bestPos : T(0);
*minCostAxis = bestAxis;

return true;
// END_CODE

